const theme=document.getElementById('theme');let saved;try{saved=localStorage.getItem('cb-library-theme')}catch{}function setTheme(dark){document.body.classList.toggle('dark',dark);theme.setAttribute('aria-checked',String(dark));theme.querySelector('.thumb').textContent=dark?'☾':'☀';document.querySelectorAll('.logo').forEach(img=>img.src=`assets/couchbase-logo${dark?'-dark':''}.svg`)}setTheme(saved==='dark'||(!saved&&matchMedia('(prefers-color-scheme: dark)').matches));theme.addEventListener('click',()=>{const dark=!document.body.classList.contains('dark');setTheme(dark);try{localStorage.setItem('cb-library-theme',dark?'dark':'light')}catch{}});let timer;function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>t.classList.remove('show'),2200)}async function copy(text,button){try{await navigator.clipboard.writeText(text);toast('Copied')}catch{toast('Select and copy the link from your address bar')}}document.getElementById('share').onclick=()=>copy(location.origin+location.pathname);document.getElementById('copy-prompt').onclick=()=>copy(document.getElementById('prompt-text').textContent);
